import React from "react";
import { COLORS } from "../constants/theme";

const LINKS = ["Rings", "Necklaces", "Earrings"];

export default function MobileDrawer({ menuOpen, setMenuOpen, scrollTo, width = 280 }) {
  const handleNav = (id) => {
    scrollTo(id);
    setMenuOpen(false);
  };

  const linkStyle = {
    display: "block",
    width: "100%",
    textAlign: "left",
    padding: "14px 0",
    background: "none",
    border: "none",
    borderBottom: `1px solid ${COLORS.border}`,
    fontSize: 16,
    color: COLORS.text,
  };

  return (
    <nav
      className="md:hidden"
      aria-hidden={!menuOpen}
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width,
        height: "100vh",
        background: COLORS.surfaceBase,
        zIndex: 1, // sits behind the sliding page (zIndex 2)
        paddingTop: 84, // clears the top bar height so links don't sit under it
        overflowY: "auto",
      }}
    >
      <div className="flex flex-col px-6">
        {LINKS.map((c) => (
          <button key={c} onClick={() => handleNav("shop")} tabIndex={menuOpen ? 0 : -1} style={linkStyle}>
            {c}
          </button>
        ))}
        <button onClick={() => handleNav("craft")} tabIndex={menuOpen ? 0 : -1} style={linkStyle}>
          The Craft
        </button>
        <button onClick={() => handleNav("faq")} tabIndex={menuOpen ? 0 : -1} style={{ ...linkStyle, borderBottom: "none" }}>
          FAQ
        </button>
      </div>
    </nav>
  );
}
